#[no_mangle]
pub unsafe extern "C" fn fifocache(a:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if a.is_null()||n<2||n>26{return -1}let x=std::slice::from_raw_parts(a,n);let(c,ops)=(x[0],x[1]);if !(1..=6).contains(&c)||!(0..=8).contains(&ops)||n!=2+3*ops as usize{return -1}let(mut keys,mut vals)=([0i64;6],[0i64;6]);let(mut z,mut h,mut m,mut g)=(0usize,0u8,0u8,0usize);let mut q=[0u8;8];for i in 0..ops as usize{let(op,key,v)=(x[2+3*i],x[3+3*i],x[4+3*i]);if !(0..=15).contains(&key)||(op!=0&&op!=1){return -1}if op==0{if !(0..=255).contains(&v){return -1}if let Some(j)=(0..z).find(|&j|keys[j]==key){for t in j+1..z{keys[t-1]=keys[t];vals[t-1]=vals[t]}z-=1}if z==c as usize{for t in 1..z{keys[t-1]=keys[t];vals[t-1]=vals[t]}z-=1}keys[z]=key;vals[z]=v;z+=1}else{if v!=0{return -1}if let Some(j)=(0..z).find(|&j|keys[j]==key){h+=1;q[g]=vals[j] as u8}else{m+=1;q[g]=255}g+=1}}let need=4+g+2*z;if out.is_null()||cap<need{return -2}let b=std::slice::from_raw_parts_mut(out,cap);b[0]=h;b[1]=m;b[2]=z as u8;b[3]=g as u8;b[4..4+g].copy_from_slice(&q[..g]);for i in 0..z{b[4+g+2*i]=keys[i] as u8;b[5+g+2*i]=vals[i] as u8}need as i64}
